import{_ as a,o,c as i,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Planificación Académica: Proyecto Sociotecnológico IV (Trimestre XI)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_IV/Planificacion_Trimestre_IV-XI.md","filePath":"materias/Proyecto_Sociotecnologico_IV/Planificacion_Trimestre_IV-XI.md"}'),t={name:"materias/Proyecto_Sociotecnologico_IV/Planificacion_Trimestre_IV-XI.md"};function r(c,e,s,d,l,u){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="planificacion-academica-proyecto-sociotecnologico-iv-trimestre-xi" tabindex="-1">Planificación Académica: Proyecto Sociotecnológico IV (Trimestre XI) <a class="header-anchor" href="#planificacion-academica-proyecto-sociotecnologico-iv-trimestre-xi" aria-label="Permalink to &quot;Planificación Académica: Proyecto Sociotecnológico IV (Trimestre XI)&quot;">​</a></h1><p>En este trimestre se ejecuta el diseño integral y el desarrollo profundo de la solución tecnológica, aplicando metodologías formales de ingeniería, patrones de arquitectura de software avanzados y construcción de prototipos de nivel industrial.</p><hr><h2 id="📅-trimestre-xi-gestion-de-proyectos-diseno-arquitectonico-y-construccion-unidades-4-y-5" tabindex="-1">📅 Trimestre XI: Gestión de Proyectos, Diseño Arquitectónico y Construcción (Unidades 4 y 5) <a class="header-anchor" href="#📅-trimestre-xi-gestion-de-proyectos-diseno-arquitectonico-y-construccion-unidades-4-y-5" aria-label="Permalink to &quot;📅 Trimestre XI: Gestión de Proyectos, Diseño Arquitectónico y Construcción (Unidades 4 y 5)&quot;">​</a></h2><h3 id="📝-evaluacion-1-gestion-de-proyectos-y-metodologia-de-desarrollo-unidad-4" tabindex="-1">📝 Evaluación 1: Gestión de Proyectos y Metodología de Desarrollo (Unidad 4) <a class="header-anchor" href="#📝-evaluacion-1-gestion-de-proyectos-y-metodologia-de-desarrollo-unidad-4" aria-label="Permalink to &quot;📝 Evaluación 1: Gestión de Proyectos y Metodología de Desarrollo (Unidad 4)&quot;">​</a></h3><p><strong>Objetivo:</strong> Aplicar la metodología de desarrollo de software/hardware adaptada a estándares de ingeniería profesional.</p><ul><li>Metodologías de ciclo de vida adaptadas: Scrum escalado, RUP/OpenUP o cascada adaptativa según el proyecto.</li><li>Gestión de la configuración y control de versiones profesional (Git, GitFlow, Integración Continua preliminar).</li><li>Gestión del alcance y control de cambios en los requerimientos.</li><li><strong>Actividad:</strong> <strong>Dossier de Gestión Metodológica y Configuración del Repositorio.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-diseno-sociotecnologico-y-modelado-arquitectonico-unidad-5" tabindex="-1">📝 Evaluación 2: Diseño Sociotecnológico y Modelado Arquitectónico (Unidad 5) <a class="header-anchor" href="#📝-evaluacion-2-diseno-sociotecnologico-y-modelado-arquitectonico-unidad-5" aria-label="Permalink to &quot;📝 Evaluación 2: Diseño Sociotecnológico y Modelado Arquitectónico (Unidad 5)&quot;">​</a></h3><p><strong>Objetivo:</strong> Diseñar la arquitectura del sistema bajo principios de modularidad, alta disponibilidad y seguridad.</p><ul><li>Diseño de Arquitectura de Software: Arquitecturas en Capas, Hexagonal / Clean Architecture, Microservicios o APIs RESTful.</li><li>Modelado UML formal completo: Diagramas de Casos de Uso, Actividades, Secuencia, Clases y Diagramas de Despliegue.</li><li>Diseño de Interfaces y Experiencia de Usuario (UI/UX) accesible y adaptativa (<em>responsive</em>).</li><li><strong>Actividad:</strong> <strong>Dossier de Modelado Arquitectónico y Especificación Técnica.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-diseno-de-datos-seguridad-e-integracion-hardware-software-unidades-4-y-5" tabindex="-1">📝 Evaluación 3: Diseño de Datos, Seguridad e Integración Hardware/Software (Unidades 4 y 5) <a class="header-anchor" href="#📝-evaluacion-3-diseno-de-datos-seguridad-e-integracion-hardware-software-unidades-4-y-5" aria-label="Permalink to &quot;📝 Evaluación 3: Diseño de Datos, Seguridad e Integración Hardware/Software (Unidades 4 y 5)&quot;">​</a></h3><p><strong>Objetivo:</strong> Diseñar la persistencia de datos relacional/no relacional y los protocolos de comunicación y seguridad.</p><ul><li>Modelado de bases de datos relacionales normalizadas (PostgreSQL / MariaDB) o bases de datos NoSQL según el alcance.</li><li>Seguridad de la información: cifrado de datos en reposo y en tránsito, autenticación JWT / OAuth2 y políticas de acceso.</li><li>Integración con componentes de hardware, sensores, microcontroladores o redes de telecomunicaciones (si aplica).</li><li><strong>Actividad:</strong> <strong>Defensa del Modelo de Datos y Esquema de Seguridad.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-construccion-y-demostracion-del-prototipo-avanzado-unidad-5" tabindex="-1">📝 Evaluación 4: Construcción y Demostración del Prototipo Avanzado (Unidad 5) <a class="header-anchor" href="#📝-evaluacion-4-construccion-y-demostracion-del-prototipo-avanzado-unidad-5" aria-label="Permalink to &quot;📝 Evaluación 4: Construcción y Demostración del Prototipo Avanzado (Unidad 5)&quot;">​</a></h3><p><strong>Objetivo:</strong> Codificar los módulos nucleares del sistema y demostrar el funcionamiento del prototipo en entorno de pruebas.</p><ul><li>Implementación del sistema con buenas prácticas de codificación (SOLID, Clean Code, linters).</li><li>Conexión a la base de datos y ejecución de los casos de uso principales.</li><li>Demostración en vivo del software ante el jurado evaluador institucional y tutores.</li><li><strong>Actividad:</strong> <strong>2do Informe de Avance y Demostración Operativa en Vivo.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Al finalizar el Trimestre XI, los estudiantes cuentan con el 2do informe de avance aprobado, la arquitectura de ingeniería consolidada y un prototipo funcional avanzado que demuestra la viabilidad técnica de la solución, listo para las pruebas de campo, optimización e implantación final.</p>',19)])])}const g=a(t,[["render",r]]);export{p as __pageData,g as default};
